// Jenkinsfile
import groovy.json.JsonOutput

pipeline {
    agent any

    environment {
        // Non-secret endpoint. Prefer configuring this as a managed/global variable.
        MONITORING_ENDPOINT = 'https://monitoring.example.internal/api/v1/jenkins/health'
    }

