                        branchName   : env.BRANCH_NAME,
                        gitCommit    : env.GIT_COMMIT
                    ].findAll { key, value -> value != null && value.toString().trim() }

                    def commandOutput = { String command ->
                        return sh(
                            script: """#!/bin/sh
                                set +x
                                ${command} 2>/dev/null || true
                            """,
                            returnStdout: true
                        ).trim()
                    }

                    // Keep system collection limited to operational health information.
                    def report = [
                        reportType  : 'jenkins-agent-health',
                        timestamp   : new Date().format("yyyy-MM-dd'T'HH:mm:ssXXX"),
                        jenkins     : [
                            jobName     : env.JOB_NAME,
                            buildNumber : env.BUILD_NUMBER,
                            buildUrl    : env.BUILD_URL,
                            nodeName    : env.NODE_NAME
                        ],
                        environment : safeEnvironment,
                        agent       : [
                            hostname      : commandOutput('hostname'),
                            os            : commandOutput('uname -srm'),
                            uptime        : commandOutput('uptime'),
                            cpuCount      : commandOutput('getconf _NPROCESSORS_ONLN'),
                            memorySummary : commandOutput("free -m | awk 'NR==2 {print \"total_mb=\" \\$2 \",used_mb=\" \\$3 \",available_mb=\" \\$7}'"),
                            diskUsage     : commandOutput("df -P -x tmpfs -x devtmpfs | awk 'NR==1 || NR>1 {print}'"),
                            loadAverage   : commandOutput("cat /proc/loadavg || uptime")
                        ],
                        runtimes    : [
                            java   : commandOutput('java -version 2>&1 | head -n 1'),
                            git    : commandOutput('git --version'),
                            docker : commandOutput('docker --version')
                        ],
                        // Add only reviewed, non-secret configuration values here.
                        approvedConfig : [
                            agentLabels : env.NODE_LABELS ?: ''
                        ]
                    ]

                    writeFile(
                        file: 'health-report.json',
                        text: JsonOutput.prettyPrint(JsonOutput.toJson(report))
                    )

                    archiveArtifacts artifacts: 'health-report.json', fingerprint: false
                }
            }
        }

        stage('Send Health Report') {
            steps {
                withCredentials([
                    string(credentialsId: 'monitoring-api-token', variable: 'MONITOR_TOKEN')
                ]) {
                    sh '''#!/bin/sh
                        set +x
                        set -eu

                        # Require TLS for outbound health reporting.
                        case "$MONITORING_ENDPOINT" in
                            https://*) ;;
                            *)
                                echo "Monitoring endpoint must use HTTPS."
                                exit 1
                                ;;
                        esac

                        # Pass the authorization header through stdin rather than
                        # placing the token directly on the command line.
                        {
                            printf 'header = "Authorization: Bearer %s"\\n' "$MONITOR_TOKEN"
                            printf 'header = "Content-Type: application/json"\\n'
                            printf 'request = "POST"\\n'
                            printf 'fail-with-body\\n'
                            printf 'silent\\n'
                            printf 'show-error\\n'
                        } | curl \
                            --config - \
                            --data-binary @health-report.json \
                            "$MONITORING_ENDPOINT"
