### `cmd/detect/main.go`

```go
package main

import (
	"fmt"
	"os"
	"strings"
)

// levenshtein returns the edit distance between two strings.
func levenshtein(a, b string) int {
	a = strings.ToLower(a)
	b = strings.ToLower(b)

	dp := make([][]int, len(a)+1)
	for i := range dp {
		dp[i] = make([]int, len(b)+1)
	}

	for i := 0; i <= len(a); i++ {
		dp[i][0] = i
	}
	for j := 0; j <= len(b); j++ {
		dp[0][j] = j
	}

	for i := 1; i <= len(a); i++ {
		for j := 1; j <= len(b); j++ {
			cost := 0
			if a[i-1] != b[j-1] {
				cost = 1
			}

			dp[i][j] = min(
				dp[i-1][j]+1,      // deletion
				dp[i][j-1]+1,      // insertion
				dp[i-1][j-1]+cost, // substitution
			)
		}
	}

	return dp[len(a)][len(b)]
}

func min(values ...int) int {
	result := values[0]
	for _, v := range values[1:] {
		if v < result {
			result = v
		}
	}
	return result
}

func main() {
	if len(os.Args) != 3 {
		fmt.Fprintf(os.Stderr, "Usage: %s <expected-package> <observed-package>\n", os.Args[0])
		os.Exit(2)
	}

	expected := os.Args[1]
	observed := os.Args[2]
	distance := levenshtein(expected, observed)

	fmt.Printf("Expected: %q\nObserved: %q\nEdit distance: %d\n",
		expected, observed, distance)

	switch {
	case expected == observed:
		fmt.Println("Result: exact match")
	case distance <= 2:
		fmt.Println("Result: WARNING — names are highly similar; verify module path, publisher, and checksum.")
	default:
		fmt.Println("Result: names are not especially similar, but normal dependency review still applies.")
	}
}
```

### Run it

```bash
go run ./cmd/detect github.com/example/securelib github.com/example/secur3lib
```

Example output:

```text
