const fs = require("fs");
const path = require("path");

const INDICATORS = [
  {
    id: "clipboard-api",
    severity: "high",
    pattern: /\b(navigator\.clipboard|clipboardy|electron\.clipboard|pbcopy|xclip)\b/i,
    description: "Clipboard API or clipboard utility reference"
  },
  {
    id: "wallet-address-regex",
    severity: "high",
    pattern: /(bc1[a-z0-9]{20,}|0x[a-f0-9]{40}|[13][a-km-zA-HJ-NP-Z1-9]{25,34})/i,
    description: "Potential cryptocurrency wallet-address pattern"
  },
  {
    id: "process-hook",
    severity: "medium",
    pattern: /\b(preinstall|postinstall|prepare)\b/i,
    description: "Lifecycle hook reference"
  },
  {
    id: "child-process",
    severity: "high",
    pattern: /\b(require\(["']child_process["']\)|execSync|spawnSync|powershell|curl\s|wget\s)/i,
    description: "Command-execution capability"
  },
  {
    id: "obfuscation",
    severity: "medium",
    pattern: /\b(Buffer\.from\(.+base64|eval\(|Function\(|unescape\(|atob\()\b/i,
    description: "Potential code-obfuscation or dynamic execution pattern"
  },
  {
    id: "remote-payload",
    severity: "high",
    pattern: /\bhttps?:\/\/[^\s"'`]+/i,
    description: "Hard-coded remote URL"
  }
];

function walk(directory) {
  const files = [];

  for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
    if (entry.name === "node_modules" || entry.name.startsWith(".")) {
      continue;
    }

    const fullPath = path.join(directory, entry.name);

    if (entry.isDirectory()) {
      files.push(...walk(fullPath));
    } else if (/\.(js|cjs|mjs|json)$/i.test(entry.name)) {
      files.push(fullPath);
    }
  }

  return files;
}

function scanFile(filePath) {
  const content = fs.readFileSync(filePath, "utf8");
  const findings = [];

  for (const indicator of INDICATORS) {
    if (indicator.pattern.test(content)) {
      findings.push({
        file: filePath,
        indicator: indicator.id,
        severity: indicator.severity,
        description: indicator.description
      });
    }
  }

  return findings;
}

function scanDirectory(targetDirectory) {
  const files = walk(targetDirectory);
  return files.flatMap(scanFile);
}

module.exports = {
  scanDirectory,
  scanFile,
  INDICATORS
};
