#!/usr/bin/env node

const fs = require("node:fs");
const path = require("node:path");
const { auditProject } = require("../lib/audit");
const { uploadReport } = require("../lib/upload");

function usage() {
  console.log(`
Usage:
  license-compliance audit [--output report.json]
  license-compliance upload --endpoint <url> --token <token> [--output report.json]

Commands:
  audit     Create a local dependency license report.
  upload    Explicitly upload a previously generated report.

Notes:
  - This tool reads package manifests and lockfiles only.
  - It does not inspect .env files, private keys, credentials, or arbitrary config files.
  - Upload requires an explicit command and endpoint.
`);
}

async function main() {
  const [, , command, ...args] = process.argv;

  if (!command || command === "--help" || command === "-h") {
    usage();
    process.exit(0);
  }

  const outputIndex = args.indexOf("--output");
  const outputFile =
    outputIndex >= 0 && args[outputIndex + 1]
      ? args[outputIndex + 1]
      : "license-compliance-report.json";

  if (command === "audit") {
    const report = await auditProject(process.cwd());
    fs.writeFileSync(outputFile, JSON.stringify(report, null, 2) + "\n");

    console.log(`License report written to ${path.resolve(outputFile)}`);
    console.log(`Dependencies scanned: ${report.summary.totalDependencies}`);
    console.log(`Unknown licenses: ${report.summary.unknownLicenses}`);
    process.exit(report.summary.unknownLicenses > 0 ? 2 : 0);
  }

  if (command === "upload") {
    const endpointIndex = args.indexOf("--endpoint");
    const tokenIndex = args.indexOf("--token");

    const endpoint = endpointIndex >= 0 ? args[endpointIndex + 1] : null;
    const token = tokenIndex >= 0 ? args[tokenIndex + 1] : null;

    if (!endpoint || !token) {
      console.error("Error: upload requires --endpoint and --token.");
      process.exit(1);
    }

    if (!fs.existsSync(outputFile)) {
      console.error(
        `Error: report file not found: ${path.resolve(outputFile)}. Run audit first.`
      );
      process.exit(1);
    }

    const report = JSON.parse(fs.readFileSync(outputFile, "utf8"));
    await uploadReport({ endpoint, token, report });

    console.log("License report uploaded successfully.");
    return;
  }

  console.error(`Unknown command: ${command}`);
  usage();
  process.exit(1);
}

main().catch((error) => {
  console.error(error.stack || error.message);
  process.exit(1);
});
```

### `lib/audit.js`

```js
const fs = require("node:fs");
const path = require("node:path");

function readJson(file) {
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

function normalizeLicense(license) {
  if (!license) return "UNKNOWN";

  if (typeof license === "string") return license;

  if (typeof license === "object" && typeof license.type === "string") {
    return license.type;
  }

  if (Array.isArray(license)) {
    return license.map(normalizeLicense).join(" OR ");
  }

  return "UNKNOWN";
}

function findPackageJsons(nodeModulesDir) {
  const results = [];
  const visited = new Set();

  function walk(directory) {
    let entries;

    try {
      entries = fs.readdirSync(directory, { withFileTypes: true });
    } catch {
      return;
    }

    for (const entry of entries) {
      if (!entry.isDirectory() || entry.name === ".bin") continue;

      const fullPath = path.join(directory, entry.name);

      if (entry.name.startsWith("@")) {
        walk(fullPath);
        continue;
      }

      const packageJson = path.join(fullPath, "package.json");

      if (fs.existsSync(packageJson) && !visited.has(packageJson)) {
        visited.add(packageJson);
        results.push(packageJson);
      }
    }
  }

  walk(nodeModulesDir);
  return results;
}

async function auditProject(projectDir) {
  const rootPackagePath = path.join(projectDir, "package.json");

  if (!fs.existsSync(rootPackagePath)) {
    throw new Error(`No package.json found in ${projectDir}`);
  }

  const rootPackage = readJson(rootPackagePath);
  const nodeModulesDir = path.join(projectDir, "node_modules");

  const dependencies = [];

  if (fs.existsSync(nodeModulesDir)) {
    for (const packagePath of findPackageJsons(nodeModulesDir)) {
      try {
        const pkg = readJson(packagePath);

        dependencies.push({
          name: pkg.name || path.basename(path.dirname(packagePath)),
          version: pkg.version || "UNKNOWN",
          license: normalizeLicense(pkg.license),
          repository:
            typeof pkg.repository === "string"
              ? pkg.repository
              : pkg.repository?.url || null
        });
      } catch {
        // Skip malformed package manifests rather than reading unrelated files.
      }
    }
  }

