import * as pulumi from "@pulumi/pulumi";

const config = new pulumi.Config();
const stateBucketName = config.require("stateBucketName");
const allowedCiRoleArn = config.require("allowedCiRoleArn");

// KMS key used to encrypt Pulumi state objects.
const stateKey = new aws.kms.Key("pulumi-state-key", {
    description: "KMS key for Pulumi state encryption",
    enableKeyRotation: true,
    deletionWindowInDays: 30,
    policy: pulumi.all([
        aws.getCallerIdentity({}),
        aws.getRegion({}),
    ]).apply(([identity, region]) => JSON.stringify({
        Version: "2012-10-17",
        Statement: [
            {
                Sid: "EnableRootPermissions",
                Effect: "Allow",
                Principal: { AWS: `arn:aws:iam::${identity.accountId}:root` },
                Action: "kms:*",
                Resource: "*",
            },
            {
                Sid: "AllowPulumiCIUseOfKey",
                Effect: "Allow",
                Principal: { AWS: allowedCiRoleArn },
                Action: [
                    "kms:Encrypt",
                    "kms:Decrypt",
                    "kms:ReEncrypt*",
                    "kms:GenerateDataKey*",
                    "kms:DescribeKey",
                ],
                Resource: "*",
            },
        ],
    })),
});

const stateBucket = new aws.s3.Bucket("pulumi-state-bucket", {
    bucket: stateBucketName,

    // Required before enabling Object Lock. Must be chosen at bucket creation.
    objectLockEnabled: true,

    versioning: {
        enabled: true,
    },

    serverSideEncryptionConfiguration: {
        rule: {
            applyServerSideEncryptionByDefault: {
                sseAlgorithm: "aws:kms",
                kmsMasterKeyId: stateKey.arn,
            },
            bucketKeyEnabled: true,
        },
    },

    lifecycleRules: [
        {
            id: "retain-state-history",
            enabled: true,
            noncurrentVersionExpiration: {
                days: 365,
            },
        },
    ],

    tags: {
        Purpose: "PulumiState",
        SecurityControl: "StateIntegrity",
    },
});

new aws.s3.BucketPublicAccessBlock("pulumi-state-public-access-block", {
    bucket: stateBucket.id,
    blockPublicAcls: true,
    blockPublicPolicy: true,
    ignorePublicAcls: true,
    restrictPublicBuckets: true,
});

// Retain prior state versions for a period. Governance mode allows authorized
// break-glass recovery while preventing accidental or low-privilege deletion.
new aws.s3.BucketObjectLockConfigurationV2("pulumi-state-object-lock", {
    bucket: stateBucket.id,
    rule: {
        defaultRetention: {
            mode: "GOVERNANCE",
            days: 30,
